homio_time.name:
[[[
  const t = states['sensor.homio_current_time'];
  return t ? t.state : '';
]]]

homio_room.extra_styles:
@media only screen and (max-width: 1249px) { .button-card-main { position: fixed !important; } }
@media (min-width: 1250px) {
  #mobile_logo { display: none !important; }
}
ha-ripple,
.mdc-ripple-surface::before,
.mdc-ripple-surface::after {
  display: none !important;
  opacity: 0 !important;
  background: transparent !important;
}
ha-card:hover,
ha-card:active,
ha-card:focus {
  filter: none !important;
  box-shadow: none !important;
  outline: none !important;
}

card.background:
[[[
  const img = variables.image || "lounge";
  const pos = variables.image_position || "center center";
  return "linear-gradient(to bottom, rgba(51,51,51,0.7) 0%, rgba(51,51,51,0.7) 50%, rgba(51,51,51,0.5) 100%), "
    + "url('/homio_dashboard/images/Homio/rooms/" + img + ".jpg') " + pos + " / cover no-repeat";
]]]

mobile_logo.display:
[[[
  if (window.innerWidth >= 1250) return 'none';
  const nav = states['input_boolean.homio_mobile_navigation'];
  return (nav && nav.state === 'on') ? 'none' : 'block';
]]]

custom_fields.temperature:
[[[
  if (!variables.show_temp || !variables.temp_sensor || !states[variables.temp_sensor]) return '';
  const eid = variables.temp_sensor;
  const st = states[eid];
  const isClimate = String(eid).indexOf('climate.') === 0;
  let temperatureValue;
  let unit;
  if (isClimate) {
    temperatureValue = parseFloat(st.attributes && st.attributes.current_temperature);
    unit = '°C';
  } else {
    temperatureValue = parseFloat(st.state);
    unit = (st.attributes && st.attributes.unit_of_measurement) ? st.attributes.unit_of_measurement : '°';
  }
  if (isNaN(temperatureValue)) return '';
  const temperature = temperatureValue.toFixed(1);
  const isF = String(unit).indexOf('F') !== -1;
  let label = '';
  if (isF) {
    if (temperatureValue <= 60) label = 'Very Cold';
    else if (temperatureValue <= 67) label = 'Cool';
    else if (temperatureValue <= 74) label = 'Comfortable';
    else label = 'Very Hot';
  } else {
    if (temperatureValue <= 15.99) label = 'Very Cold';
    else if (temperatureValue <= 17.99) label = 'Cool';
    else if (temperatureValue <= 20.99) label = 'Comfortable';
    else label = 'Very Hot';
  }
  return temperature + unit + ' - ' + label;
]]]

custom_fields.humidity:
[[[
  if (!variables.show_humid || !variables.humid_sensor || !states[variables.humid_sensor]) return '';
  const humidityValue = parseFloat(states[variables.humid_sensor].state);
  if (isNaN(humidityValue)) return '';
  const humidity = humidityValue.toFixed(0);
  if (humidityValue <= 29.99) return 'Humidity is very dry at ' + humidity + '%';
  if (humidityValue <= 60.99) return 'Humidity is good at ' + humidity + '%';
  return 'Humidity is high at ' + humidity + '%';
]]]
